catalog_script_client.script:
function showLoadingMessage() {
    // Fallback: show field message
    g_form.showFieldMsg('certificate_expiry', 'Loading...', 'info');
    g_form.showFieldMsg('certificate_name', 'Loading...', 'info');
    g_form.showFieldMsg('serial_number', 'Loading...', 'info');
}

function showErrorMessage(error) {
    // Fallback: show field message
    g_form.showFieldMsg('certificate_expiry', error, 'error');
    g_form.showFieldMsg('certificate_name', error, 'error');
    g_form.showFieldMsg('serial_number', error, 'error');
}

function hideLoadingMessage() {
    g_form.hideFieldMsg('certificate_expiry', true);
    g_form.hideFieldMsg('certificate_name', true);
    g_form.hideFieldMsg('serial_number', true);
}

// --- onChange Client Script ---
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }

    var deviceSysId = g_form.getValue("device");
    g_form.clearValue("csr");
    g_form.clearValue("serial_number");
    g_form.clearValue("certificate_expiry");
    g_form.clearValue("certificate_name");
    g_form.clearValue("device_name");
    g_form.clearValue("hostname");
    g_form.clearValue("bind_address");
    g_form.clearValue("bind_port");
    g_form.clearValue("download_certificate_only");
	g_form.clearValue("validation_message");
	g_form.clearValue("certificate_creation_time");

    g_form.setDisplay("csr", true);

    // Show spinner before async call
    showLoadingMessage();

    var ga = new GlideAjax("GetDeviceCertificateDetails");
    ga.addParam("sysparm_name", "getDeviceCertificateDetails");
    ga.addParam("sysparm_deviceSysId", deviceSysId);
    ga.getXMLAnswer(function(answer) {
        // Hide spinner after response
        hideLoadingMessage();
        try {
            var res = JSON.parse(answer);
            if (res.error) {
                throw new Error(res.error);
            }
			if (res.length == 0) {
				return;
			}
            g_form.setValue("certificate_name", res.name || "");
            g_form.setValue("serial_number", res.serialNumber || "");
			g_form.setValue("certificate_creation_time", res.createdDate || "");
			g_form.setValue("certificate_status", res.status || "");

            var expiryString = res.expiryDate;
            if (expiryString) {
                // Parse as UTC
                var utcDate = new Date(expiryString + "Z"); // "Z" tells JS it's UTC

                // Get components in user's local timezone
                var year = utcDate.getFullYear();
                var month = ("0" + (utcDate.getMonth() + 1)).slice(-2);
                var day = ("0" + utcDate.getDate()).slice(-2);
                var hours = ("0" + utcDate.getHours()).slice(-2);
                var minutes = ("0" + utcDate.getMinutes()).slice(-2);
                var seconds = ("0" + utcDate.getSeconds()).slice(-2);

                // Format as "YYYY-MM-DD HH:mm:ss"
                var localDateTime = year + "-" + month + "-" + day + " " + hours + ":" + minutes + ":" + seconds;

                g_form.setValue("certificate_expiry", localDateTime);
            }
        } catch (error) {
            var message = error.message || "Couldn't parse the response for the certificate details.";
            alert(message);
			showErrorMessage(message);
            var ga = new GlideAjax('IDCLogger');
            ga.addParam("sysparm_name", "idcLogger");
            ga.addParam("sysparm_logLevel", "Error");
            ga.addParam("sysparm_script", "GetDeviceDetails");
            ga.addParam("sysparm_message", message);
            ga.getXML(function() {});
        }
    });
}
